import {
  handleHttpError,
  enableNotifications,
  checkInput,
} from '/static/js/common/functions.prod.js';
import {
  showErrorMessage,
  showSuccessMessage,
} from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  NProgress.done();
  let e = $('[name="csrftoken"]')[0].content;
  ($(document).ajaxError(function (e, t) {
    handleHttpError(t.status);
  }),
    $(document).ajaxStart(function () {
      NProgress.start();
    }),
    $(document).ajaxComplete(function () {
      (checkInput(), NProgress.done());
    }),
    $(document).on('htmx:beforeRequest', function () {
      NProgress.start();
    }),
    $(document).on('htmx:afterSwap', function () {
      (checkInput(), NProgress.done());
    }),
    window.addEventListener('popstate', () => {
      (NProgress.start(),
        setTimeout(() => {
          NProgress.done();
        }, 1e3));
    }));
  let t = new URLSearchParams(window.location.search).get('view_page');
  (t &&
    (NProgress.start(),
    $.ajax({
      type: 'GET',
      url: `?page=${t}`,
      success: function (e) {
        ($('.mainContent').empty().append(e), NProgress.done());
      },
    })),
    document.body.addEventListener('htmx:responseError', function (e) {
      handleHttpError(e.detail.xhr.status);
    }),
    $('main').on('click', '.checkbox', async function () {
      $(this).prop('checked')
        ? await enableNotifications()
        : showErrorMessage(
            gettext('Notifications Silenced'),
            gettext('You will not receive notifications')
          );
    }),
    $('main').on('click', 'button', function () {
      let t = $('.inputHolder').find('input'),
        o = t.attr('id'),
        s = t.val().trim(),
        n = t.data('edit-name');
      0 != s.length
        ? (n &&
            n.length &&
            $.ajax({
              type: 'POST',
              headers: { 'X-CSRFToken': e },
              url: '?action=edit_personal_info',
              data: JSON.stringify({ editName: o, editValue: s }),
              success: function (e) {
                e.status
                  ? showSuccessMessage(
                      'Details Changed',
                      `You have updated your ${n}`
                    )
                  : showErrorMessage(
                      'Details Not Changed',
                      'An error occurred try again.'
                    );
              },
            }),
          console.log(o),
          'login_password' == o &&
            $.ajax({
              type: 'POST',
              url: '?action=confirm_password',
              headers: { 'X-CSRFToken': e },
              data: JSON.stringify({ password: s }),
              success: function (e) {
                if (e.status)
                  return (
                    showSuccessMessage(
                      'Password Confirmed',
                      'Enter your new password to change it.'
                    ),
                    void $('.mainContent').empty().append(e.html)
                  );
                e.logout
                  ? (showErrorMessage(
                      'Logging you out',
                      'Too many password attempts.'
                    ),
                    NProgress.start(),
                    $('button').prop('disabled', !0),
                    setTimeout(() => {
                      window.location.reload();
                    }, 2e3))
                  : showErrorMessage(
                      'Password Failed',
                      'You will be logged out after 3 incorrect attempts.'
                    );
              },
            }))
        : showErrorMessage('Empty Field', 'Kindly Fill in the Blank Space');
    }));
  let o = !1;
  $('main').on('click', '.logout_content_button', function () {
    o
      ? $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': e },
          url: '?action=logout',
          success: function (e) {
            e.status
              ? (showSuccessMessage('Logged Out', 'Refreshing your page'),
                setTimeout(() => {
                  window.location.reload();
                }, 2e3))
              : showErrorMessage('Could Not Log Out', 'Kindly Try again.');
          },
        })
      : (showErrorMessage(
          'Are you sure?',
          'Kindly click Logout again to confirm'
        ),
        (o = !0));
  });
});
